import { describe, it } from 'vitest';
import { parse } from '../src/parse';
import { classify, type TransactionFacts } from '../src/classify';
import { computeVerdict } from '../src/enforce';
import { encodeLines } from '../src/encode';
import { walkNodes } from '../src/model';
import { nodeStartLine } from '../src/locate';

function probe(label: string, text: string, line: number, ch: number, dir: 'back' | 'fwd') {
  const doc = parse(text);
  const lines = encodeLines(doc);
  let fromCh: number, toCh: number, fromLine: number, toLine: number, deletesLineBoundary = false;
  if (dir === 'back') {
    if (ch === 0) { fromLine = line - 1; toLine = line - 1; fromCh = (lines[line-1] ?? '').length; toCh = 0; deletesLineBoundary = true; }
    else { fromLine = line; toLine = line; fromCh = ch - 1; toCh = ch; }
  } else {
    if (ch === (lines[line] ?? '').length) { fromLine = line; toLine = line; fromCh = ch; toCh = 0; deletesLineBoundary = true; }
    else { fromLine = line; toLine = line; fromCh = ch; toCh = ch + 1; }
  }
  const rangeEnd = deletesLineBoundary ? { line: fromLine + 1, ch: 0 } : { line: toLine, ch: toCh };
  const facts: TransactionFacts = {
    userEvent: dir === 'back' ? 'delete.backward' : 'delete.forward',
    isComposition: false,
    changedLineSpans: [{ fromLine, toLine, insertedText: '', fromCh, toCh, rangeEnd, ...(deletesLineBoundary ? { deletesLineBoundary: true } : {}) }],
    cursorBefore: { line, ch },
  };
  const cls = classify(facts, doc);
  const edit = { from: { line: fromLine, ch: fromCh }, to: rangeEnd, insert: '', cursorBefore: { line, ch } };
  const v = computeVerdict(cls, doc, edit);
  const forced = computeVerdict('boundary-crossing-edit', doc, edit);
  console.log(`\n--- ${label} [${line}:${ch}] ${dir}`);
  console.log(`    class=${cls} verdict=${v.kind}${v.kind==='veto'?'('+v.reason+')':''} | forced=${forced.kind}${forced.kind==='veto'?'('+forced.reason+')':''}${forced.kind==='rewrite'?' edits='+JSON.stringify(forced.edits):''}`);
}

const DOC = '# One\n\npara one\n\n## Two\n\npara two\n\n## Three\n\npara three\n';

describe('measure', () => {
  it('line map', () => {
    const doc = parse(DOC);
    encodeLines(doc).forEach((l, i) => console.log(`${i}: ${JSON.stringify(l)}`));
    for (const entry of walkNodes(doc)) {
      const n: any = (entry as any).node ?? entry;
      console.log(`node ${n.id} kind=${n.kind} start=${nodeStartLine(doc, n.id)} lines=${JSON.stringify(n.lines)} gap=${JSON.stringify(n.trailingGap)}`);
    }
  });

  it('shapes', () => {
    probe('heading content start (## Two, ch3)', DOC, 4, 3, 'back');
    probe('heading line start (## Two, ch0)', DOC, 4, 0, 'back');
    probe('heading mid-marker (## Two, ch2 -> deletes # at ch1)', DOC, 4, 2, 'back');
    probe('Delete at end of para one (fwd into ## Two)', DOC, 2, 8, 'fwd');
    probe('first-node heading content start (# One, ch2)', DOC, 0, 2, 'back');
    probe('list item content start (control)', '- alpha\n- beta\n', 1, 2, 'back');
    probe('para content start after heading', DOC, 2, 0, 'back');
  });
});
